create table if not exists logistics_agency_consolidations (consolidation_id text primary key, agency_id text not null, name text not null, mode text not null, origin text not null, destination text not null, provider text, parent_reference text, status text not null, package_count integer default 0, piece_count integer default 0, weight_lb numeric default 0, created_at timestamptz not null, updated_at timestamptz not null);
create index if not exists idx_agency_consolidations_tenant on logistics_agency_consolidations(agency_id, created_at desc);
create table if not exists logistics_agency_consolidation_items (item_id text primary key, agency_id text not null, consolidation_id text not null, package_id text not null, pieces integer not null, weight_lb numeric, created_at timestamptz not null, unique(agency_id,consolidation_id,package_id));
create table if not exists logistics_agency_freight_documents (freight_document_id text primary key, agency_id text not null, document_type text not null, number text not null, consolidation_id text, carrier text, origin text, destination text, metadata jsonb default '{}'::jsonb, status text not null, created_at timestamptz not null, updated_at timestamptz not null);
create table if not exists logistics_agency_delivery_routes (route_id text primary key, agency_id text not null, name text not null, destination_province text not null, driver_employee_id text, vehicle_reference text, package_ids jsonb default '[]'::jsonb, stops integer default 0, status text not null, created_at timestamptz not null, updated_at timestamptz not null);
create table if not exists logistics_agency_tariffs (tariff_id text primary key, agency_id text not null, name text not null, currency text not null, basis text not null, amount numeric not null, applies_to text not null, destination_province text, status text not null, created_at timestamptz not null, updated_at timestamptz not null);
create table if not exists logistics_agency_invoices (agency_invoice_id text primary key, agency_id text not null, billed_agency_reference text not null, consolidation_id text, currency text not null, subtotal numeric not null, fees numeric not null, notes text, total numeric not null, balance_due numeric not null, status text not null, created_at timestamptz not null, updated_at timestamptz not null);
